using System.ComponentModel;
using System.Text.Json;
using Microsoft.Extensions.AI;

Console.WriteLine("Research Agent Starting...");

var topic = args.Length > 0 ? string.Join(" ", args) : "the benefits of renewable energy";
Console.WriteLine($"Researching topic: {topic}\n");

// Configure the AI client (expects OPENAI_API_KEY environment variable)
var endpoint = Environment.GetEnvironmentVariable("OPENAI_ENDPOINT") ?? "https://api.openai.com/v1";
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY") ?? throw new InvalidOperationException(
    "Set the OPENAI_API_KEY environment variable to use this agent.");
var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

var client = new OpenAI.OpenAIClient(apiKey);
var chatClient = client.GetChatClient(model).AsIChatClient();

// Set up tools
var notepad = new NotepadTool();
var searchTool = new WebSearchTool();

var chatOptions = new ChatOptions
{
    Tools = [
        AIFunctionFactory.Create(searchTool.SearchWeb),
        AIFunctionFactory.Create(notepad.AddNote),
        AIFunctionFactory.Create(notepad.GetNotes),
    ]
};

// Build the agent loop
var messages = new List<ChatMessage>
{
    new(ChatRole.System, """
        You are a research agent. Your job is to research a given topic thoroughly.

        Follow these steps:
        1. Search the web for information about the topic (perform 2-3 searches with different queries)
        2. Take notes on key findings using the note-taking tool
        3. After gathering enough information, retrieve all your notes and provide a comprehensive summary

        Always take notes as you find information, then produce a final summary at the end.
        """),
    new(ChatRole.User, $"Please research the following topic and provide a summary: {topic}")
};

const int maxIterations = 15;
for (int i = 0; i < maxIterations; i++)
{
    var response = await chatClient.GetResponseAsync(messages, chatOptions);
    messages.Add(response.Messages.Last());

    // Check if the model wants to call tools
    if (response.FinishReason == ChatFinishReason.ToolCalls)
    {
        continue;
    }

    // Final response from the agent
    Console.WriteLine("=== Research Summary ===\n");
    Console.WriteLine(response.Messages.Last().Text);
    break;
}

Console.WriteLine("\n=== Notes Collected ===");
foreach (var note in notepad.Notes)
{
    Console.WriteLine($"  • {note}");
}

// --- Tool Definitions ---

public class WebSearchTool
{
    [Description("Searches the web for information on a query. Returns a list of relevant snippets.")]
    public string SearchWeb([Description("The search query")] string query)
    {
        Console.WriteLine($"  [Tool] Searching web for: \"{query}\"");

        // Simulated web search results for demonstration purposes.
        // In production, replace with a real search API (Bing, Google, etc.)
        var results = GetSimulatedResults(query);
        return JsonSerializer.Serialize(new { query, results });
    }

    private static string[] GetSimulatedResults(string query)
    {
        var q = query.ToLowerInvariant();

        if (q.Contains("renewable energy") || q.Contains("clean energy"))
            return [
                "Renewable energy sources include solar, wind, hydroelectric, geothermal, and biomass. Global renewable capacity grew by 50% in 2024, reaching over 4,200 GW.",
                "The cost of solar energy has dropped 90% since 2010. Wind energy costs have fallen by 70% in the same period.",
                "Renewable energy now accounts for over 30% of global electricity generation as of 2025."
            ];

        if (q.Contains("solar") || q.Contains("photovoltaic"))
            return [
                "Solar PV capacity exceeded 2,000 GW globally in 2025. China, the US, and India are the largest markets.",
                "Modern solar panels achieve 22-24% efficiency, with experimental cells reaching over 47%.",
                "Solar energy creates 3x more jobs per megawatt than fossil fuel plants."
            ];

        if (q.Contains("wind"))
            return [
                "Global wind capacity reached 1,100 GW in 2025. Offshore wind is the fastest-growing segment.",
                "Modern wind turbines can power over 3,000 homes each and have a lifespan of 25-30 years.",
                "Wind energy avoids approximately 1.1 billion tonnes of CO2 emissions annually."
            ];

        if (q.Contains("benefits") || q.Contains("advantages"))
            return [
                "Key benefits: reduced greenhouse gas emissions, energy independence, job creation, and lower long-term costs.",
                "Renewables improve air quality, reducing respiratory illnesses and saving healthcare costs estimated at $100B annually.",
                "Distributed renewable generation improves grid resilience and energy security."
            ];

        return [
            $"Various sources discuss '{query}' as an important topic in current research and policy discussions.",
            $"Recent studies on '{query}' show promising developments and growing public interest.",
            $"Experts suggest '{query}' will play a significant role in the coming decade."
        ];
    }
}

public class NotepadTool
{
    public List<string> Notes { get; } = [];

    [Description("Adds a research note. Use this to record key findings during research.")]
    public string AddNote([Description("The note content to save")] string note)
    {
        Notes.Add(note);
        Console.WriteLine($"  [Tool] Note added ({Notes.Count} total)");
        return $"Note saved. You now have {Notes.Count} note(s).";
    }

    [Description("Retrieves all saved research notes.")]
    public string GetNotes()
    {
        Console.WriteLine($"  [Tool] Retrieving {Notes.Count} notes");
        if (Notes.Count == 0)
            return "No notes saved yet.";
        return JsonSerializer.Serialize(Notes);
    }
}

